import math,re

def _field(text,name,pattern):
    match=re.search(pattern,text,re.I|re.M)
    if not match:raise ValueError("missing or invalid chrony field: "+name)
    return match

def assess_drift(samples,max_offset_seconds=0.1):
    if not isinstance(samples,list) or not samples:raise ValueError("at least one tracking sample required")
    if not isinstance(max_offset_seconds,(int,float)) or isinstance(max_offset_seconds,bool) or not math.isfinite(max_offset_seconds) or max_offset_seconds<=0:
        raise ValueError("positive finite offset limit required")
    parsed=[]
    for text in samples:
        if not isinstance(text,str):raise TypeError("tracking samples must be text")
        leap=_field(text,"Leap status",r"^Leap status\s*:\s*(.+?)\s*$").group(1)
        stratum=int(_field(text,"Stratum",r"^Stratum\s*:\s*(\d+)\s*$").group(1))
        current=_field(text,"System time",r"^System time\s*:\s*([+-]?[0-9.eE+-]+)\s+seconds\s+(fast|slow)\s+of\s+NTP time\s*$")
        offset=float(current.group(1))*(1 if current.group(2).lower()=="fast" else -1)
        if not math.isfinite(offset):raise ValueError("nonfinite system offset")
        parsed.append({"offset_seconds":offset,"stratum":stratum,"leap_status":leap})
    current=parsed[-1];trend="stable"
    if len(parsed)>1 and abs(current["offset_seconds"])>abs(parsed[-2]["offset_seconds"])+1e-9:trend="worsening"
    synchronized=current["leap_status"].lower()=="normal" and 1<=current["stratum"]<=15
    if not synchronized:status="unsynchronised"
    elif abs(current["offset_seconds"])>max_offset_seconds:status="offset_out_of_tolerance"
    else:status="healthy"
    return {**current,"trend":trend,"status":status,
        "next":"inspect chronyc sources/tracking and restore host time synchronization before changing certificate validity or keys" if status!="healthy" or trend=="worsening" else "continue monitoring offset and source freshness"}
